local function level() return (workspace:FindFirstChild("teleporter pads") or {}) and (function() for _, v in ipairs(workspace:FindFirstChild("teleporter pads"):GetDescendants()) do if v:IsA("StringValue") and v.Value == "roads 3" then return v.Parent end end return "Unable To Find Level 3 On Roads" end)() or "No Teleporter Pads" end
while true do local s=workspace[game:GetService("Players").LocalPlayer.Name].Sphere_powerup local l=level() firetouchinterest(s,l,0)task.wait()firetouchinterest(s,l,1)task.wait()local c=workspace["roads 3"]["coin chest"].main firetouchinterest(s,c,0)task.wait()firetouchinterest(s,c,1)task.wait(.5)local w=workspace["roads 3"]["teleporter win"]firetouchinterest(s,w,0)task.wait()firetouchinterest(s,w,1)task.wait(.5)end
